/**
 * Applies a JSON Merge Patch to a task the actor sees, as `PATCH /v1/tasks/{taskKey}` says:
 * the status and its cancel reason, checked against the statuses of the space the task is in
 * after the patch, the due date that moves the start and keeps the duration, the move of the
 * task and its subtasks, the parent, `If-Match` required with `description`
 * (`400 request.invalid` with an issue on the header). Records the changes of status,
 * priority and due date, the changes of the priority and the due date of a task by the same
 * actor within 60 seconds merged into one entry. Emits `task.updated.v1` and
 * `task.status-changed.v1` as the public route says. Internal token: actor `user`,
 * organization required.
 * @summary Change a task
 */
export const updateTaskInternalPathTaskKeyRegExp = new RegExp('^[A-Z]{2,5}-[1-9][0-9]{0,8}$');


export const UpdateTaskInternalParams = zod.object({
  "taskKey": zod.string().regex(updateTaskInternalPathTaskKeyRegExp).describe('Key of the task.')
})

export const UpdateTaskInternalHeader = zod.object({
  "If-Match": zod.string().optional().describe('`"<version>"` the change was made from.')
})

export const updateTaskInternalBodyNameMax = 300;

export const updateTaskInternalBodyDescriptionMax = 50000;

export const updateTaskInternalBodyCancelNoteMax = 500;

export const updateTaskInternalBodyEstimateMinutesMax = 60000;

export const updateTaskInternalBodyParentKeyOneRegExp = new RegExp('^[A-Z]{2,5}-[1-9][0-9]{0,8}$');


export const UpdateTaskInternalBody = zod.object({
  "name": zod.string().min(1).max(updateTaskInternalBodyNameMax).optional().describe('"Nom de la tâche", as typed; surrounding spaces are removed, and a name made only of spaces\nis refused with `400 request.invalid`.\n'),
  "description": zod.string().max(updateTaskInternalBodyDescriptionMax).nullish().describe('"Description", Markdown; `null` when there is none.'),
  "status": zod.enum(['triage', 'backlog', 'todo', 'progress', 'review', 'testing', 'waiting', 'blocked', 'done', 'cancelled']).optional().describe('Key of a task status, in the order of the workflow: `triage` ("À trier"), `backlog` ("À\nplanifier"), `todo` ("À faire"), `progress` ("En cours"), `review` ("En revue"), `testing`\n("En validation"), `waiting` ("En attente"), `blocked` ("Bloqué"), `done` ("Terminé") and\n`cancelled` ("Annulé"). `STATUS_KEYS` of `@cadenway/contracts`; a space renames or hides a\nstatus, it never adds or removes a key.\n'),
  "cancelReason": zod.union([zod.enum(['duplicate', 'wontdo', 'scope', 'obsolete']).describe('Why a task was cancelled ("Motif d’annulation"): `duplicate` ("Doublon"), `wontdo` ("Ne sera\npas fait"), `scope` ("Hors périmètre") or `obsolete` ("Obsolète"). `CANCEL_REASONS` of\n`@cadenway/contracts`. A closed set: another reason would be a breaking change.\n'),zod.null()]).optional().describe('Required when the status becomes `cancelled`; changes the reason of a cancelled task;\nrefused on a task that is not cancelled after the patch. Leaving `cancelled` clears it.\n'),
  "cancelNote": zod.string().max(updateTaskInternalBodyCancelNoteMax).nullish().describe('"Précision" of a cancellation, trimmed; `null` clears it.'),
  "priority": zod.enum(['urgente', 'haute', 'moyenne', 'basse']).optional().describe('Priority of a task, from the most to the least urgent: `urgente` ("Urgente"), `haute`\n("Haute"), `moyenne` ("Moyenne", the default) and `basse` ("Basse"). `PRIORITY_KEYS` of\n`@cadenway/contracts`. A closed set: another priority would be a breaking change.\n'),
  "dueDate": zod.iso.date().nullish().describe('New due date; `null` removes it. Without `startDate` in the same patch, the start\nmoves with it and the duration is kept (see `PATCH /v1/tasks/{taskKey}`).\n'),
  "startDate": zod.iso.date().nullish().describe('New first day of the work; `null` removes it.'),
  "estimateMinutes": zod.int().min(1).max(updateTaskInternalBodyEstimateMinutesMax).nullish().describe('"Estimation", in whole minutes ("8 h" is `480`); `null` for none.'),
  "listId": zod.uuid().optional().describe('The list to move the task to ("Déplacer vers…"), in this space or another; its\nsubtasks follow, and a subtask leaves its parent first.\n'),
  "parentKey": zod.union([zod.string().regex(updateTaskInternalBodyParentKeyOneRegExp).describe('Key of a task, the only way a task is named outside task-service: the prefix of the space\nit was created in, a dash and a number. A key never changes, also when the task moves to\nanother space or its space changes prefix, and is never given to another task.\n'),zod.null()]).optional().describe('The task to attach this one to ("Devenir sous-tâche de…"), which brings it and its\nsubtasks to the list of the parent; `null` detaches it ("Détacher de CAD-482").\n')
}).describe('JSON Merge Patch of a task; an empty object changes nothing. The assignees, the labels and\nthe checklist are collections: they change through their own routes, and a patch ignores\nthe members it does not declare, `assigneeIds` and `labels` included.\n')

export const updateTaskInternalResponseKeyRegExp = new RegExp('^[A-Z]{2,5}-[1-9][0-9]{0,8}$');

export const updateTaskInternalResponseParentKeyOneRegExp = new RegExp('^[A-Z]{2,5}-[1-9][0-9]{0,8}$');
export const updateTaskInternalResponseSubtaskCountsTotalMin = 0;

